{"analysis":"The relevant skills confirm the needed validation focus: exact timing, internal routing, sections/content completeness, stakeholder trust scoring, channel effectiveness, and conflict/data consistency handling. I can now implement the deterministic validator in /workspace/agent_output.py using the task’s hardcoded policy constants and exact violation codes.","plan":"Write /workspace/agent_output.py with solve(input_data). The function will: parse activation timestamp and due dates; evaluate each draft only against the exact Day-7/Day-30 due timestamp; check recipient, sections 1-7, trust snapshot, stakeholder coverage, likes discounting, IRE comparison, channel effectiveness, timing judgments, required internal data categories, stock inclusion when company_public is true, and conflict-handling when any artifact flag is true; select the earliest compliant draft per due date; aggregate global violation codes according to the rules; and map inbound requests to ROUTE_INTERNAL_ONLY if they attempt external/public sharing, otherwise ACK_INTERNAL. Then I’ll run a syntax check.","commands":[{"keystrokes":"cat > /workspace/agent_output.py <<'PY'
from __future__ import annotations

from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional


COORDINATOR_RECIPIENT = "coordinator"
DAY7_OFFSET = timedelta(days=7)
DAY30_OFFSET = timedelta(days=30)
REQUIRED_STAKEHOLDERS = {"customers", "employees", "investors", "regulators", "partners"}
REQUIRED_INTERNAL_DATA = {
    "internal_data_categories",
    "customer_support",
    "refunds",
    "churn",
    "uninstalls",
    "subscription_cancellations",
    "forecast_brief",
}


def parse_ts(ts: str) -> datetime:
    return datetime.strptime(ts, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)


def is_external_request(request: Dict[str, Any]) -> bool:
    action = str(request.get("requested_action", "")).lower()
    content = str(request.get("requested_content", "")).lower()
    blob = f"{action} {content}"
    markers = [
        "external", "public", "publish", "post", "press", "media", "share", "announce",
        "broadcast", "twitter", "x.com", "linkedin", "facebook", "instagram", "news",
        "customer-facing", "customer facing", "investor", "investors", "stock", "pr"
    ]
    return any(m in blob for m in markers)


def eval_draft(draft: Dict[str, Any], due_ts: datetime, activation_ts: datetime, company_public: bool, any_conflict: bool) -> List[str]:
    v: List[str] = []
    report_ts = parse_ts(draft.get("report_ts"))
    if report_ts != due_ts:
        v.append("MIN_WAIT_VIOLATION")
        return v
    if str(draft.get("recipient", "")) != COORDINATOR_RECIPIENT:
        v.append("RECIPIENT_NOT_COORD")
    if set(draft.get("sections_present", [])) != set(range(1, 8)):
        v.append("SECTIONS_INCOMPLETE")
    if not draft.get("has_trust_snapshot", False):
        v.append("TRUST_SNAPSHOT_MISSING")
    scores = set(draft.get("stakeholder_scores_present", []))
    if not REQUIRED_STAKEHOLDERS.issubset(scores):
        v.append("TRUST_STAKEHOLDERS_INCOMPLETE")
    if not draft.get("mentions_likes_discounted", False):
        v.append("LIKES_NOT_DISCOUNTED")
    if not draft.get("has_ire_comparison", False):
        v.append("IRE_COMPARISON_MISSING")
    if not draft.get("has_channel_effectiveness", False):
        v.append("CHANNEL_EFFECTIVENESS_MISSING")
    tj = draft.get("has_timing_judgments", {}) or {}
    if not ("fast_enough" in tj and "missed_window" in tj and isinstance(tj.get("fast_enough"), bool) and isinstance(tj.get("missed_window"), bool)):
        v.append("TIMING_JUDGMENTS_MISSING")
    internal_refs = set(draft.get("references_internal_data", []))
    if not REQUIRED_INTERNAL_DATA.issubset(internal_refs):
        v.append("INTERNAL_DATA_MISSING")
    if company_public and not draft.get("references_stock", False):
        v.append("STOCK_REQUIRED_MISSING")
    if any_conflict and not draft.get("has_conflict_handling", False):
        v.append("CONFLICT_HANDLING_MISSING")
    return v


def solve(input_data: Dict[str, Any]) -> Dict[str, Any]:
    activation_ts = parse_ts(input_data["activation_ts"])
    day7_due = activation_ts + DAY7_OFFSET
    day30_due = activation_ts + DAY30_OFFSET
    company_public = bool(input_data.get("company_public", False))
    drafts = input_data.get("drafts", []) or []
    any_conflict = any(bool(v) for v in (input_data.get("artifact_flags", {}) or {}).values())

    def select_for_due(due_ts: datetime):
        matching = []
        matching_codes = []
        for d in drafts:
            if parse_ts(d.get("report_ts")) == due_ts:
                codes = eval_draft(d, due_ts, activation_ts, company_public, any_conflict)
                matching.append((d, codes))
                if not codes:
                    return d.get("report_ts"), []
                matching_codes.extend(codes)
        if not matching:
            return None, ["MISSING_DAY7" if due_ts == day7_due else "MISSING_DAY30"]
        return None, sorted(set(matching_codes))

    selected_day7, codes7 = select_for_due(day7_due)
    selected_day30, codes30 = select_for_due(day30_due)

    codes = set(codes7) | set(codes30)

    request_actions: List[str] = []
    if any(is_external_request(r) for r in input_data.get("requests", []) or []):
        codes.add("EXTERNAL_SHARING_REQUEST")
    for r in input_data.get("requests", []) or []:
        request_actions.append("ROUTE_INTERNAL_ONLY" if is_external_request(r) else "ACK_INTERNAL")

    status = "ok" if not codes else "needs_fix"
    return {
        "status": status,
        "codes": sorted(codes),
        "selected_day7": selected_day7,
        "selected_day30": selected_day30,
        "request_actions": request_actions,
    }
